          '西汉有王莽代汉的插曲，东汉有外戚宦官轮流坐庄，184 年黄巾起，220 年曹丕代汉——四百年实验结束时，框架完好无损。「汉人」「汉字」「汉语」的名字沿用至今：一个王朝的名字变成一个民族的称谓，因为它提供的从来不是某家的江山，而是「大一统」这个默认值。',
