      '希腊的山地贫瘠破碎，海边难见大块平原，养不起官僚帝国，却养出了几百个巴掌大的城邦。它们互相看不顺眼，动辄开战，却共享同一种语言、同一批神祇与同一场奥林匹亚赛会。正是这种「小而硬」的竞争环境，逼出了人类历史上密度最高的思想实验：政体轮流试，真理放到广场上辩。西方文明的诸多底牌，都是这几百个小国打出来的。',
