          '内部推行军区制：行省改成军区，士兵领田屯戍，兵农合一，帝国退无可退，却总能耗得起。外交上，收买、联姻、封号与教义传播都被用成武器，让对手不战自乱，「拜占庭式」从此成了欧洲语言里权谋的代名词。代价是内耗同样出名：726—843年的圣像破坏运动把帝国撕成两半，砸圣像与护圣像的流血持续了一个多世纪。',
