          '霸权的另一面是强制：敢于绕行的船只，据载会被巡弋的战船拦截甚至摧毁。室利佛逝几乎不造宏伟石庙，它的财富是流动的——胡椒、龙脑香、樟脑、象牙在此转手东西方，税与差价入账，再以朝贡的名义遣使中国，换回册封与贸易特权。海峡是它的城壕，也是它的税卡。',
