          '终结来得突然：1025 年，南印度注辇王拉金德拉出动舰队横渡孟加拉湾，奇袭其港口，掳走国王——世界史上少见的跨洋远征，争的不只是货物，正是马六甲这道咽喉。三佛齐此后一蹶不振，都城迁往詹卑，十三世纪末被新兴的满者伯夷吞并。',
