          '它与爪哇的夏连特拉王朝联姻互市，婆罗浮屠的兴起与这层海上网络互为表里——那座石造曼陀罗的出资者，与海峡税卡的主人是一家人。一座没有巨型石庙的帝国，却把佛教从恒河口接力送到长安与奈良：信仰跟着航线走，航线跟着季风走，而季风停泊的地方，就是室利佛逝。',
