          '这个国家把商人性格刻进了制度：行政首脑是两名任期一年的苏菲特，元老院与公民大会分享权力，介于斯巴达与雅典之间。它不设公民兵，打仗靠雇佣军与盟友——省下的人力都投进港口、船坞与账房。这种制度高效，却有一个致命软肋：商人习惯在谈判桌上让步，未必肯为一座远方的城池流尽自己的血。后来的一切悲剧，都埋在这里。',
