          '李成桂的政变不只是换国王。高丽以佛教立国数百年，新王朝却把朱子学奉为唯一官学：佛寺田产被没收，僧团被迁出京城，儒家的宗法、服丧、嫡庶之制写进国家法典。科举考四书五经，太学叫成均馆，官制从正一品排到从九品——一整套按「礼」运转的国家机器，在汉阳组装完毕。',
          '实验结果双面。好的一面：朝鲜成为东亚社会秩序最稳固的国家之一，《朝鲜王朝实录》一千八百九十三卷，五百余年从不中断，是世界最完整的王朝档案。坏的一面：国家把朱子学当真理标准，政争全变成「谁更正宗」的学派审判——十五世纪末以来的历次士祸中，成百上千士人被杀或流放，死因常常只是一篇文章、一份名单。',
          '对外它奉行「事大交邻」：对明朝贡之勤居各藩属之首，一年数贡，事无巨细请求裁定；对女真各部、对日本则以邻邦之礼分而治之。小国在大国夹缝里的生存术，被这个王朝修炼成了制度。',
