          '1895 年明成皇后在宫中被日本浪人杀害；1897 年高宗改国号「大韩帝国」试图自救；1905 年朝鲜成为日本保护国；1910 年《韩日合并条约》签订，王朝终结。但五百年的遗产没有终结：谚文成了今天近八千万人的日常文字，《训民正音》与王朝实录 1997 年同列世界记忆遗产。一个亡了国的王朝，活在它发明的字母里。',
