          '转机在 1009 年：禁军将领李公蕴受禅建李朝，次年便把都城迁出山谷，安在红河冲积平原的正中。1054 年，李圣宗改国号为「大越」——与北方帝国对举之意，呼之欲出。升龙很快长成河港辐辏的都会，向南的商路与向北的朝贡通道都从这里出发。从郡县废墟里长出来的国家，起点不是模仿，而是把一千年学到的制度，变成自己的。',
