          '它的战车走重装路线：每车三人——驭手、持盾卫兵、持矛武士——冲阵如铁锤，与埃及双人机动战车风格迥异。都城哈图沙建在花岗岩山脊上，狮门与王门镇守要冲，地下凿有巨大粮仓；文献里它被称为「千神之城」，条约宣誓时常召唤「哈提之地的千神」作证。雅兹勒卡亚岩石圣殿的浮雕长廊里，诸神列队而行——帝国把万神殿直接刻进了山体。',
