          '埃及版刻在卡纳克与拉美西姆神庙的墙上，赫梯版泥板藏在哈图沙档案里，两份文本在三千多年后被考古学家对上了号。1970 年，土耳其政府把条约复制品赠给联合国，悬于纽约联合国总部——人类第一次学会坐下谈判的证据，如今挂在世界外交的门口。',
