          '重逢在三千年后：1906 年起，德国考古队掘出哈图沙约三万块泥板档案；1915 年，捷克学者赫罗兹尼破译赫梯语，确认它是印欧语系最古老的文字记录——一座安纳托利亚山城，成了整个印欧语世界的文字起点。档案里还藏着胡里语的《库马尔比之歌》，学者视之为希腊《神谱》的远亲；《吉尔伽美什》的译本也躺在其中。一个只在《圣经》里被一笔带过的民族，最终成了上古史的重心。',
