          '另一份证词长在田里：美洲安第斯的作物甘薯，出现在波利尼西亚诸岛的种植园里，约 12—15 世纪间跨海而至。无论那是一场偶遇还是有计划的航程，结论都一样——波利尼西亚人的船到过美洲的边缘，比哥伦布早了至少两个世纪。1777 年，环游太平洋的库克船长在日记里发问：我们该如何解释，这个族群竟散布在世界上如此众多、彼此隔绝的角落？',
