          '「生态崩溃」是复活节岛最出名的叙事：伐光森林、推倒石像、自相残杀——贾雷德·戴蒙德把它写成人类自毁的寓言。然而近年考古研究给出另一版本：岛民本就人口有限，真正的重创是欧洲人带来的疾病与掳掠。寓言好听，证据为王——历史学家还在争论，这正是活的历史。',
