        heading: '宣言的高音与宪法的杂音',
        paragraphs: [
          '1776 年 7 月 4 日，大陆会议通过《独立宣言》，执笔者是 33 岁的弗吉尼亚律师杰斐逊。「人人生而平等」是那个世纪最锋利的政治修辞——但写下它的会场里坐着蓄奴的代表，句子里的「人」也不包括奴隶、妇女与原住民。这份宣言从一开始就不是完成时，而是一张分期兑付的支票。',
          '独立后的邦联软弱得近乎虚设：国会无权征税、没有行政首脑，十三州各设关卡互收关税。1786 年马萨诸塞的退伍军人谢斯带人武装抗税，联邦竟无兵可调——正是这场骚乱把各州代表逼回了费城。1787 年宪法交出三件套：联邦制收权、三权分立互相盯防、修正案机制留下修改接口。',
          '妥协同样写进了文本：为换取南方支持，奴隶人口按「五分之三」折算议席，贩奴贸易再宽限二十年。麦迪逊在《联邦党人文集》第 51 篇说得坦白：「如果人都是天使，就不需要任何政府。」这部宪法不是对人性的礼赞，而是对人性不信任的产物——1791 年十条权利法案补齐接口，制度开始试运行。',
        ],
