          '新家并不好过。温带气候下，故土的番薯只能在北部生长，南岛居民改以蕨根充饥；这片陆地上唯一的土生哺乳动物是蝙蝠，蛋白质只能向海鸟、鱼群与巨鸟讨要。恐鸟——十余种不会飞的巨鸟，最高的超过三米——在人类登陆后约百年内被猎杀殆尽，捕食恐鸟的哈斯特巨鹰随之灭绝。这是人类史上最快的巨兽灭绝事件之一。',
