          '内政与仪式同样精密：奥德维拉节每年净化联盟、重申忠诚，库马西的宫廷仪式规模让每一位到访的欧洲使节咋舌。19 世纪初英国使团成员鲍迪奇记录下的国王出巡与雅姆节阅兵，成了欧洲了解这座内陆帝国的第一手窗口——他笔下的库马西，整齐、威严而富庶。',
          '制度设计的巧思在联盟制：被征服的邦国不必灭祠灭庙，只要把「灵魂」交进金凳子的体系，战败者转身就是联邦成员。这让扩张的速度远超血亲吞并；代价则是中枢必须不停证明自己——每届奥巴登基都要出征，每场败仗都可能引发解体。用信仰黏住的帝国，信仰就是它的常备军。',
