          '阿散蒂的财政与大西洋奴隶贸易深度绑定：18 世纪，战俘出口是其最重要的「外汇」来源之一。这是它绕不开的污点——内陆的每一次征服，都在为海岸的贩运船供给货物。帝国同时要消化内部的张力：附庸邦时叛时服，中央靠金凳子的神圣性与军事胜利维持凝聚，一旦军事受挫，联盟立刻松动。',
          '与英国的碰撞在 19 世纪变成主旋律：从 1823 年到 1900 年，双方大战六次。1824 年阿散蒂一度阵斩英军总督麦卡锡，震动欧洲；但工业化的差距在拉大——1874 年英军攻入库马西，焚毁王宫；1896 年，普伦佩国王被流放塞舌尔。帝国的躯体被打断了，灵魂却还没交出去。',
