          '故事的结尾比开头更有力：1935 年英国恢复阿散蒂联邦，金凳子重归库马西，历代阿散蒂王延续至今，仍是加纳最有影响力的传统权威；雅阿·阿桑提娃则成为全非洲女性抵抗的象征。1957 年加纳独立时，国名取自古加纳帝国，而阿散蒂正是这个新国家的钢铁脊梁。英国人赢下了所有战役，却始终没能坐上那把凳子——它是这场百年战争里唯一没有战败的东西。',
