          '首都佩特拉本身是凿出来的：卡兹尼「宝库」其实是王陵，立面 40 米高，罗马柱式与本土装饰混成一格；峡谷两壁的墓室、祭坛与阶梯，全是双手与凿子一寸寸敲出来的。他们还发明了自己的文字——纳巴泰字母后来演变为阿拉伯字母：今天十几亿人书写的文字，祖源之一就是这座沙漠城。',
          '纳巴泰人的商业模式可以一句话概括：把风险与不便做成服务。商队不必再赌水源与向导，租他们的向导、走他们的水站、付他们的过路税；他们则把省下的每一分经营成本投回水利与道路。在没有国家的荒漠里，他们提供了一种准公共产品——安全与水的保证，这正是佩特拉在沙漠里立住两百年的真正地基。',
