          '更深的一笔在字母表：纳巴泰文演变为阿拉伯文，这条文字谱系把一个沙漠商邦与今天的整个阿拉伯世界连在一起。而他们的水利学——集水、导洪、防渗、分沙——至今仍被干旱地区的水务工程师当作古代范本研究。纳巴泰人证明了一件事：在沙漠里，把约束变成产品，约束本身就是护城河。',
