          '但斯瓦希里没有消失，它变成了语言与生活方式：斯瓦希里语以班图语法为骨、阿拉伯语词汇为皮，今天是非洲使用人口最多的语言之一，过亿人日常使用，也是非洲联盟的工作语言。拉穆老城与基尔瓦遗存列入世界遗产。它的存在修正了一种偏见：在大航海之前，非洲早已是印度洋世界的老股东——只是这段合伙史，被后来的叙事改写过。',
