          '他们的事迹多由敌人转述：希腊与罗马作者笔下的伊特鲁里亚人「最虔诚也最享乐」——精通占卜、举办赛会，妇女地位之高令希腊人侧目。墓葬是他们的自传：塔尔奎尼亚的墓室壁画里，宴会、乐舞与渔猎鲜亮如新。',
