          '他们还是字母的搬运工：从希腊殖民地学来字母，再传给罗马——今天西方人使用的字母表，走的是「腓尼基→希腊→伊特鲁里亚→拉丁」这条接力链。伊特鲁里亚语本身却没能活下来：它与周边语言都不同源，存世铭文逾万条，长文至今无法完全释读。',
