          '宗教是他们的招牌：伊特鲁里亚的占卜学在罗马沿用数百年，官方占卜官制度直接继承于伊特鲁里。可以说，罗马最早的神学与最早的下水道，来自同一批老师。罗马全盛时仍常请伊特鲁里亚裔占卜官解读闪电与鸟飞，遇到凶兆，连战役都要改期。',
