          '吞并不等于抹除：同盟者战争（前90年）后伊特鲁里亚人获得罗马公民权，精英融入元老阶层，皇帝克劳狄乌斯还能读伊特鲁里亚史书，并为之写过二十卷（已佚）——老师消失在学生的字典里，只留下词条。克劳狄乌斯还下令把占卜之学交由贵族世家世代研习，免得这门手艺绝了后。',
