          '它的隐喻价值延续到今天：老师未必是胜者，学生也未必从零开始——罗马把伊特鲁里亚的下水道、字母与占卜术全部改姓。文明的传承常常如此：名字消失了，语法活了下来。今天托斯卡纳的墓丘与博物馆陶棺上，还刻着没人完全读得懂的吊词。',
