          '爱资哈尔970年动工、988年起设讲席，从皇家清真寺长成法蒂玛的传教学府；1005年又设「达鲁·伊尔姆」（智慧之殿）收藏书籍、供养学者，光学与天文研究在宫廷有编制——这是开罗对巴格达智慧宫的应答。',
