          '11世纪初是法蒂玛的顶点：疆域从北非、西西里到埃及、汉志与叙利亚，麦加与麦地那的星期五讲道念的是开罗的名字。1021年前后，据传哈里发哈基姆一夜骑入穆卡塔姆山后再未出现，其追随者后来发展出德鲁兹社区——这个王朝的宗教光谱从来就不简单。',
          '强敌环伺：东面与逊尼的阿拔斯-塞尔柱体系对峙，北面与拜占庭在叙利亚拉锯。1060年代大饥荒与军人内斗险些压垮帝国，此后百年，开罗哈里发逐渐沦为权臣手中的图章——旗帜还在，引擎换了人。1070年代，维齐尔拜德尔·贾迈利重修开罗城墙，把南门与北门修成今天仍能看到的石门。',
