          '代价清单很长：宫廷内斗耗尽国库，11世纪后期的饥荒与瘟疫据载让开罗人口锐减；图书馆的藏书在王朝末期被变卖、散佚。帝国死了，但它最大的两件作品——开罗与爱资哈尔——继续生长到今天。开罗犹太人的「藏经窖」里，至今保存着与法蒂玛市场往来的成千上万张账单。',
