          '放在更长的时间里看，法蒂玛证明了另一种可能：在逊尼主导的中世纪世界，一个少数派王朝靠海军、财政与城市规划立国两百余年。它输掉了哈里发之争，赢下了一座至今仍按它的蓝图生长的城市。胜利的定义，从来不止一种。',
