          '等到18世纪殖民者深入内陆，密西西比文化的继承人已把空土丘当作「远古遗迹」。19—20世纪，大量土丘被推平取土、铺路盖房——圣路易斯人管自己城市叫「土丘城」。1982年，卡霍基亚列入世界遗产。',
