          '今天它仍是活的研究现场，激光雷达与磁测每年都改写一次地图。这座泥土之城提醒我们：美洲的原生城市史并不始于欧洲人的到来——它只是被推迟写进了教科书。卡霍基亚的解说牌也会特意写明：这里是一座城市，而不只是一堆土丘。',
