          '萨非最持久的遗产是一条看不见的线：从1501年起，什叶派与波斯国家绑定生长，教士体系、宗教法研修与圣陵朝拜网络在两百年里定型。今天的伊朗-伊拉克-海湾教派地理，骨架大体就是萨非与奥斯曼那条边境线。',
          '文化账同样可观：细密画、地毯纹样、园林与「波斯蓝」瓷砖经萨非宫廷定型，成为世界对波斯审美的全部想象。一个用教派立国、用艺术立身的王朝消失于1736年，却把「伊朗性」重新拼装完毕。今天伊朗的国界大体仍沿着当年与奥斯曼划定的那条线——两国边境，是那场百年战争留下的活化石。',
