      '794年，桓武天皇把都城迁到平安京——此后一千多年，日本的天皇再没有换过都城。这座城市按唐长安的棋盘缩样修建，住着一群把写诗、调香、穿衣当作终身事业的贵族。他们的时代叫平安时代：四百年里，天皇渐渐不理政事，外戚替他理，武士替外戚守边，最后武士替所有人接管了日本。但日本文化最美的那部分，恰恰诞生在这场漫长的怠政里。',
