        heading: '缘起：从长安的缩样开始',
        paragraphs: [
          '平安京按唐长安的格局缩样规划：棋盘式街道、朱雀大路纵贯南北、左右两京对称展开。遣唐使继续把唐朝的制度、佛教与风尚整船运回——桓武、嵯峨两朝的日本，几乎是长安文化最认真的海外学生。838年最后一艘遣唐使船归国后，日本停止派遣：不是关门，而是消化——此后四百年，「和风」慢慢从唐风里长出自己的脸。',
          '假名的发明是这一过程的开关。万叶假名太笨重，宫廷女官把汉字草书简化成平假名与片假名，日语从此可以按自己的语法书写。汉字仍属男性与公文的领地，女性笔下的假名反而成了文学的母语——权力忽视的地方，恰恰成了创造的地方。',
        ],
