          '同一时期，净土思想流行：末法将至的焦虑让贵族捐堂造佛，平等院凤凰堂（1053年落成）把想象中的极乐世界搬进花园。国风文化、假名文学、和歌与庭院美学——今天外国人心目中的「日本美」，底稿大多画于平安。',
