          '平氏专权二十年后于1185年败于源氏；同年源赖朝获得「守护」「地头」任命权，镰仓幕府落地。平安朝廷继续存在，但实权易手——公家再没能真正掌权，直到1868年。镰仓的位置选得意味深长：远离京都，背靠关东武士的老家——政权跟着兵源走。',
