          '吐蕃政制围绕赞普（王）运转：尚论（贵族与大臣）分层任事，军政合一的「茹」与「东岱」（翼与千户）既是行政区划也是动员单位；盟誓制度维系王与贵族，等级分明的告身臂章制度标定官员身份——这些都是后世西藏制度的前身。',
          '文化上，吐蕃从印度与唐朝两路吸收：佛经翻译规模浩大，桑耶寺（约779年落成）落成后，「七觉士」第一次出家为僧；医学、历算与造纸术一并传入。敦煌文书里保留了大量藏文写卷——吐蕃占领敦煌期间（约786—848），这座丝路文库的藏文部分成了研究帝国的第一手档案。',
