          '没有共同信仰缝合的部落联盟迅速散架：河西的吐蕃军队自成体系，属部叛离，平民起义遍及卫藏——帝国在一两代人之间解体，此后近四百年高原再未出现统一政权。藏文文献把这段岁月称为「分崩时代」，敦煌的一份藏文编年史把内战记得毫不留情，成了后世重构帝国史的关键拼图。',
