          '这套设计埋下八百年药引：皇权与教权共轭共生，也互相撕咬。1077 年皇帝亨利四世在卡诺莎雪地赤足立了三天，向教宗求饶——主教授职权之争的高潮。这道题的账单极贵：皇帝一次次南下意大利，把德意志贵族晾在后方，后者趁机坐大；红胡子腓特烈六征意大利，最终死在第三次十字军的河里。对意大利的执念吞噬了帝国的中央化窗口——当法兰西、英格兰在加固王权时，神圣罗马帝国把最好的两百年花在了亚平宁的攻防上。',
