          '它也有过想象力的巅峰：霍亨斯陶芬王朝的腓特烈一世（红胡子）六征意大利，1189 年亲率第三次十字军，却在渡河时溺亡；其后的大空位时代（1254 — 1273）无帝可选，皇权崩成碎片。1438 年起，哈布斯堡家把皇位变成自家传家宝，直到帝国最后一日——帝国的后半生，姓哈布斯堡。',
