          '对外它还得扛住东方的奥斯曼：1529 年与 1683 年维也纳两度被围，第二次靠波兰国王索别斯基与帝国联军合力解围（详见「奥斯曼帝国」条）。一个没有中央军队、没有统一税制、连常备陆军都要向各邦讨要的「帝国」，能守住维也纳，靠的是分权体制逼出来的联盟能力——散装未必是弱点。',
