          '1349 年，他在斯科普里颁行《杜尚法典》，1354 年增补至两百余条：法典大量借鉴拜占庭法，却对塞尔维亚的贵族、教会与农民关系作了本土化规定——从允许私战到限制教会地产，条款具体到近乎琐碎。这是南斯拉夫语族最早的完整法典之一，也是巴尔干中世纪社会的一张快照。',
