          '1271 年，威尼斯商人马可·波罗从这里出发东行，二十余年后在狱中口述出那本让全欧洲做梦的书（详见「马可·波罗」条）。共和国还把远洋贸易做成了国营班轮：定期船队按航线、按班次开行，武装护航，商人持股分舱——这是中世纪最接近现代航运公司的东西。',
          '造船的底气来自阿森纳：这座国家船厂占地数十公顷，工人数以千计，巅峰时期据载能一天下水一艘战舰——材料与部件在仓库里按编号流水存放，组装如搭积木。但丁在《神曲》里都拿阿森纳的修船忙乱来形容地狱的喧嚣。国家拥有并运营这样一座工厂，欧洲此前没有先例：威尼斯的国富，是造出来的。',
