          '今天全球五亿人说的西班牙语，法理上的名字仍是「卡斯蒂利亚语」；西班牙的国家形态——卡斯蒂利亚为核心、诸自治区环列——几乎就是中世纪王冠地图的当代转写。一个边区伯国靠四百年战争与一项语言政策，把自己复制成了半个地球。而王位继承法、议会传统与语言版图这些活制度，都还是那四百年战争留下的遗产。这条道路的成败，后来成为一切联合王国故事的原型。',
