          '联邦的外交同样别致：1137 年的婚约与教宗的十字军授权给了它向地中海扩张的旗号。13 世纪，海梅一世（征服者）拿下巴利阿里与瓦伦西亚；1282 年「西西里晚祷」事件后，阿拉贡应西西里人之请渡海接管了那座岛——与安茹的法国势力在地中海正面开战，一个伊比利亚国家从此把意大利当成了主场。',
