          '财政上，马拉塔继续征收希瓦吉创立的「乔特」（保护税）与「萨尔德什穆基」（岁入的百分之二十五），把税收网络铺到北印度。他们的骑兵与税收体系，让18世纪中叶的马拉塔成为次大陆最强的军事-财政复合体。',
