          '三次英马战争（1775—1818）把联盟各个击破：马拉塔骑兵打不过东印度公司的训练军与炮兵，各家族先后签约称臣。1818年佩什瓦被废，末代君王领年金流亡——马拉塔的独立史至此结束，其故地并入孟买管辖区。',
