          '马拉塔在印度史叙述中的位置很特别：它是莫卧儿之后、英国之前统治次大陆大片土地的印度教政权，被19—20世纪的民族主义者反复引用为「抵抗外来统治」的先例——希瓦吉成了民族英雄，孟买的希瓦吉火车站以他命名。',
          '它的另一遗产是马拉地语的政治地位：用本族语施政的传统，让马拉地文化圈在后来的孟买邦分裂运动中有了历史依据。一个山地联盟的存在，改变了印度对「帝国」这个词的想象。而马拉地人的身份认同，也自此有了国家的记忆。',
