          '今天首里城每年举办「琉球王朝绘卷行列」，万国津梁钟的复制品挂在首里城显眼处（原件毁于1945年战火，仅存残片）。一座小岛用四百五十年回答了一个大问题：在大国之间，小国如何不成为猎物，而成为桥梁。而在那之前，琉球的政治家们早已给出过更复杂的答案——向中国称臣、向萨摩纳贡、向四方通商，在夹缝里把「事大」做成了生存艺术。琉球史家至今仍在争论这条路线的对错，但没有人否认它的艰难。',
