          '约前590年，米底与斯基泰的夹击终结了王国。城市被放弃，文字失传了两千五百年——直到19世纪欧洲学者借贝希斯敦铭文的三体对译，才重新读出这种语言。乌拉尔图从传说回到历史，用了与现代考古学同龄的时间。',
