          '治国的底色是丹·福迪奥那句流传至今的原则：王国可以容忍不信，却不能容忍不义。这句话对内是改革的号角，对外是征伐的理由——哈里发国的正义性与扩张性，从一开始就是同一枚硬币的两面。它治下的奴隶制并未废除，这也是后世争议的核心。',
