          '今天，索科托苏丹仍是尼日利亚北方穆斯林的精神领袖，豪萨语与富拉尼文化的版图也大致沿着当年哈里发国的轮廓。它是殖民前非洲国家建构的巅峰样本，也是理解今日尼日利亚南北分野的钥匙：一个用讲道与宪章立国的政权，其遗产至今仍在政治里呼吸。它的圣战叙事在殖民时期被压制，独立后又被政治反复调用——同一份遗产的两种命运，在同一片土地上同时上演。这就是索科托留给西非的长期债项。',
