          '埃兰的国家形态很独特：不是一位专制君主，而是「苏卡勒玛赫」（大摄政）与兄弟、继承人共治的三头体制，首都轮流坐庄（阿万、安善、苏萨）。前 2300 年左右，它甚至与阿卡德的纳拉姆辛签订了一份互保盟约，盟约铭文里写得分明：阿卡德之敌即埃兰之敌，埃兰之敌即阿卡德之敌——古代近东最早的平等同盟条约之一。',
