          '这批战利品让苏萨成了「两河文物仓库」，也让埃兰与巴比伦的恩怨越结越深。中埃兰时期（前 1500 — 前 1100）是它的黄金时代：乔加赞比尔的白塔神庙至今耸立，五层之高；埃兰语楔形文字的王铭、印章与陶板，撑起了一个成熟的国家书写传统。',
