          '前 539 年居鲁士建立波斯帝国时，苏萨被立为帝国行政首都，波利斯（波斯波利斯）的管理泥板用三种文字书写，埃兰语位列其中——波斯人沿用了埃兰的行政语言、官员体系与筑渠技术。埃兰作为一个国家死了，作为波斯帝国的「行政基因」活了下来。',
