          '它还留下一个耐人寻味的规律：两千年的世仇，最后以继承收场。波斯人没有抹掉埃兰，而是搬进了它的首都、沿用了它的文字与官员；「波斯」这个名字响彻古代世界时，苏萨的城砖上仍是埃兰人的刻痕。文明的延续，有时靠的不是活到最后，而是被最强大的邻居当作模板。',
